signer.initSign(privateKey);
signer.update(payload);
var signature = Base64.getEncoder().encodeToString(signer.sign());
var json = "{\"version\":\"0.1.2\",\"os\":\"linux\",\"architecture\":\"x64\",\"archiveSha256\":\"" + hash + "\",\"signatureAlgorithm\":\"Ed25519\",\"signature\":\"" + signature + "\"}";
Files.writeString(dir.resolve("manifest-0.1.2.json"), json, StandardCharsets.UTF_8);
System.out.println(hash);
